import base64,json,linecache,sys,types,unittest
assert 'torch_npu' not in sys.modules
sources={'tensor_tuple_transport': '', 'hook_tuple_adapters': '', 'test_transport_cpu': ''}
for name,encoded in sources.items():
    source=base64.b64decode(encoded).decode()
    filename='/CPU-only-native-discovery-v3/'+name+'.py'
    module=types.ModuleType(name);module.__file__=filename
    sys.modules[name]=module
    linecache.cache[filename]=(len(source),None,source.splitlines(keepends=True),filename)
    exec(compile(source,filename,'exec'),module.__dict__)
assert 'torch_npu' not in sys.modules
import torch
assert torch.version.cuda is None
suite=unittest.defaultTestLoader.loadTestsFromModule(sys.modules['test_transport_cpu'])
